export interface ConnectorConfig {
  /** Asana Personal Access Token (PAT) from the Asana developer console. */
  asanaAccessToken: string
  /** The Asana workspace (or project) GID where the task will be created. */
  workspaceId: string
  /** Optional: GID of a pre-existing custom field in the workspace to store the Jotform submission ID. */
  customFieldIdForSubmission?: string
  /** Optional injected fetch for testing. */
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  /** Title of the Jotform form. */
  formTitle: string
  /** Unique submission identifier from Jotform. */
  submissionId: string
  /** Dynamic form fields following the pattern field_{field_id}. */
  [key: `field_${string}`]: string | undefined
}

export interface HandleResult {
  /** The Asana task GID returned on successful creation. */
  taskId: string
  /** The full Asana task response data. */
  task: AsanaTaskResponse
}

export interface AsanaTaskResponse {
  gid: string
  name: string
  notes: string
  workspace: {
    gid: string
    resource_type: string
    name: string
  }
  custom_fields: Array<{
    gid: string
    resource_type: string
    text_value: string
  }>
}

interface AsanaCreateTaskRequest {
  data: {
    name: string
    notes: string
    workspace: string
    custom_fields?: Record<string, string>
  }
}

function buildDescription(payload: JotformSubmissionPayload): string {
  const fieldEntries = Object.entries(payload)
    .filter(([key]) => key.startsWith('field_'))
    .map(([key, value]) => {
      const fieldId = key.replace('field_', '')
      return `Question: Field ${fieldId}\nAnswer: ${value ?? ''}`
    })
  return fieldEntries.join('\n\n')
}

export async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.formTitle || typeof payload.formTitle !== 'string') {
    throw new Error('Missing required field: formTitle')
  }
  if (!payload.submissionId || typeof payload.submissionId !== 'string') {
    throw new Error('Missing required field: submissionId')
  }
  if (!config.workspaceId || typeof config.workspaceId !== 'string') {
    throw new Error('Missing required config: workspaceId')
  }
  if (!config.asanaAccessToken || typeof config.asanaAccessToken !== 'string') {
    throw new Error('Missing required config: asanaAccessToken (ASANA_ACCESS_TOKEN)')
  }

  const description = buildDescription(payload)

  const requestBody: AsanaCreateTaskRequest = {
    data: {
      name: payload.formTitle,
      notes: description,
      workspace: config.workspaceId,
    },
  }

  if (config.customFieldIdForSubmission) {
    requestBody.data.custom_fields = {
      [config.customFieldIdForSubmission]: payload.submissionId,
    }
  }

  const response = await fetchImpl('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(
      `Asana API error: ${response.status} ${response.statusText} at POST https://app.asana.com/api/1.0/tasks - ${errorText}`,
    )
  }

  const result = (await response.json()) as { data: AsanaTaskResponse }
  return {
    taskId: result.data.gid,
    task: result.data,
  }
}

