            {
              data: {
                gid: 'task-123',
                name: 'Test Form',
                notes: 'Question: Field 123\nAnswer: John\n\nQuestion: Field 456\nAnswer: john@example.com',
                workspace: { gid: 'ws-1', resource_type: 'workspace', name: 'WS' },
                custom_fields: [{ gid: 'cf-sub', resource_type: 'custom_field', text_value: 'sub-1' }],
              },
            },
            201,
          )
        : jsonResponse({ error: 'not found' }, 404),
    )

    const payload: JotformSubmissionPayload = {
      formTitle: 'Test Form',
      submissionId: 'sub-1',
      field_123: 'John',
      field_456: 'john@example.com',
